/**
 * Domain types come from the Python models: the file is generated by
 * `frontedge gen` (see python/frontedge/src/frontedge/gen/typescript.py).
 * Change the model in Python and regenerate — never edit the types by hand.
 */
export type {
  ActionResult,
  ActionSpec,
  Artifact,
  ColumnSpec,
  DatasetDetail,
  DatasetInfo,
  EvalComparison,
  EvalSummary,
  Example,
  ExampleResult,
  Freshness,
  LogLine,
  MetricDirection,
  MetricEvent,
  MetricPoint,
  MetricSpec,
  ProvenanceEntry,
  Run,
  RunOption,
  RunStatus,
  Stage,
  UiConfig,
} from "./generated/types";

export { frontedgeRoles } from "./generated/types";

/**
 * Canonical stage names. `Stage.name` accepts any string — a project may add `tokenize` or
 * `deploy`; these four keep autocomplete for the common case.
 */
export type StageName = "prepare" | "train" | "eval" | "publish" | (string & {});
